const SEASONAL_DESTINATIONS=[
  {iso2:'MA',flag:'🇲🇦',categories:['sun'],image:'/assets/destination-maroc.webp'},
  {iso2:'GB',flag:'🇬🇧',categories:['city'],image:'/assets/destination-london.webp'},
  {iso2:'US',flag:'🇺🇸',categories:['city','long'],image:'/assets/destination-usa.webp'},
  {iso2:'AE',flag:'🇦🇪',categories:['sun','long'],image:'/assets/destination-dubai.webp'},
  {iso2:'JP',flag:'🇯🇵',categories:['city','long'],image:'/assets/destination-japon.webp'},
  {iso2:'TH',flag:'🇹🇭',categories:['sun','long'],image:'/assets/destination-bangkok.webp'},
  {iso2:'ES',flag:'🇪🇸',categories:['sun'],image:'/assets/destination-canaries.webp'},
  {iso2:'IT',flag:'🇮🇹',categories:['city'],image:'/assets/destination-rome.webp'}
];
const POPULAR_DESTINATIONS=['FR','ES','IT','US','JP','AE','TH','MA','GB'];
const t=TEXT[LANG],seasonalText=SEASONAL_TEXT[LANG],rechargeText=RECHARGE_TEXT[LANG],cartText=CART_TEXT[LANG],displayNames=new Intl.DisplayNames([LOCALES[LANG]],{type:'region'});
const destinationImages={FR:'/assets/destination-france.webp',MA:'/assets/destination-maroc.webp',US:'/assets/destination-usa.webp',JP:'/assets/destination-japon.webp',GB:'/assets/destination-london.webp',AE:'/assets/destination-dubai.webp',TH:'/assets/destination-bangkok.webp',ES:'/assets/destination-canaries.webp',IT:'/assets/destination-rome.webp'};
const fallbackIso=['FR','MA','US','JP'];
const fallbackCountries=fallbackIso.map(iso2=>({iso2,name:displayNames.of(iso2),name_fr:displayNames.of(iso2),flag_emoji:{FR:'🇫🇷',MA:'🇲🇦',US:'🇺🇸',JP:'🇯🇵'}[iso2],price_from:null,product_count:0}));
let countries=[];

const countryName=country=>country.name||displayNames.of(country.iso2)||country.name_fr||country.iso2;
const money=value=>new Intl.NumberFormat(LOCALES[LANG],{style:'currency',currency:'EUR'}).format(Number(value||0));
const q=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const legalText=value=>value.replace('{terms}',LEGAL[LANG].terms).replace('{privacy}',LEGAL[LANG].privacy);

function cachedCountryImage(iso2){try{return localStorage.getItem(`hopon-country-image-${iso2}`);}catch(_){return null;}}
async function resolveCountryImage(country){
  if(destinationImages[country.iso2])return destinationImages[country.iso2];const cached=cachedCountryImage(country.iso2);if(cached)return cached;
  try{const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:countryName(country),gsrnamespace:'0',gsrlimit:'1',prop:'pageimages',piprop:'thumbnail',pithumbsize:'900',format:'json',origin:'*'});const response=await fetch(`https://${LANG}.wikivoyage.org/w/api.php?${params}`);if(!response.ok)throw new Error();const data=await response.json();const image=Object.values(data.query?.pages||{}).find(page=>page.thumbnail?.source)?.thumbnail?.source;if(!image)throw new Error();try{localStorage.setItem(`hopon-country-image-${country.iso2}`,image);}catch(_){}return image;}catch(_){return destinationImages[country.iso2]||'/assets/hopon-pool.webp';}
}
const countryImageObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(async entry=>{if(!entry.isIntersecting)return;countryImageObserver.unobserve(entry.target);const country=countries.find(item=>item.iso2===entry.target.dataset.countryImage);if(!country)return;const source=await resolveCountryImage(country);if(source&&entry.target.isConnected)entry.target.src=source;}),{rootMargin:'300px'}):null;
function hydrateCountryImages(root=document){root.querySelectorAll('[data-country-image]').forEach(async image=>{if(countryImageObserver)return countryImageObserver.observe(image);const country=countries.find(item=>item.iso2===image.dataset.countryImage);if(country){const source=await resolveCountryImage(country);if(source&&image.isConnected)image.src=source;}});}
async function api(path,options={}){const response=await fetch(API+path,{cache:'no-store',...options,headers:{'Content-Type':'application/json','X-Hopon-Language':LANG,...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||t.serviceUnavailable);return data;}
function toast(message){const el=q('#toast');el.textContent=message;el.classList.add('on');setTimeout(()=>el.classList.remove('on'),3200);}

function renderCountries(items){
  q('#destination-grid').innerHTML=items.map((country,index)=>{const name=countryName(country);return `<article class="destination-card" tabindex="0" data-country="${escapeHtml(country.iso2)}"><img class="destination-image" data-country-image="${escapeHtml(country.iso2)}" src="${destinationImages[country.iso2]||'/assets/hopon-pool.webp'}" alt="${escapeHtml(t.travelLandscape)} - ${escapeHtml(name)}" referrerpolicy="no-referrer" ${index?'loading="lazy"':''}><div class="destination-body"><div class="destination-title"><h3>${escapeHtml(country.flag_emoji||'🌍')} ${escapeHtml(name)}</h3><span>${Number(country.product_count||0)} ${t.plans}</span></div><p class="destination-meta">${t.autoActivation}</p><div class="destination-price"><b>${country.price_from==null?t.ratesUnavailable:`${t.from} ${money(country.price_from)}`}</b><button class="round-arrow" aria-label="${escapeHtml(t.viewPlans)} ${escapeHtml(name)}">→</button></div></div></article>`;}).join('');
  hydrateCountryImages(q('#destination-grid'));document.querySelectorAll('.destination-card').forEach(card=>{const open=()=>openPlans(card.dataset.country);card.addEventListener('click',open);card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});});
}
let seasonalFilter='all';
function renderSeasonal(){
  const section=q('#inspirations'),grid=q('#seasonal-grid'),empty=q('#seasonal-empty');if(!section||!grid)return;
  const candidates=SEASONAL_DESTINATIONS.map(item=>({...item,country:countries.find(country=>country.iso2===item.iso2)})).filter(item=>seasonalFilter==='all'||item.categories.includes(seasonalFilter));
  const available=candidates.filter(item=>item.country&&Number(item.country.product_count||0)>0&&item.country.price_from!=null);
  const unavailable=candidates.filter(item=>!available.includes(item));
  const items=seasonalFilter==='all'?[...available,...unavailable].slice(0,6):[...available,...unavailable];
  if(!items.length){section.hidden=true;grid.innerHTML='';if(empty){empty.hidden=false;empty.textContent=seasonalText.empty;}return;}
  section.hidden=false;if(empty)empty.hidden=true;
  grid.innerHTML=items.map(item=>{const [city,badge]=seasonalText.cards[item.iso2],isAvailable=item.country&&Number(item.country.product_count||0)>0&&item.country.price_from!=null,flag=item.country?.flag_emoji||item.flag;return `<article class="seasonal-card${isAvailable?'':' is-unavailable'}" ${isAvailable?'tabindex="0"':''} data-country="${item.iso2}" ${isAvailable?`aria-label="${escapeHtml(seasonalText.view)} ${escapeHtml(city)}"`:'aria-disabled="true"'}><img src="${item.image}" alt="${escapeHtml(city)}" ${item.iso2==='MA'?'':'loading="lazy"'}><div class="seasonal-card-body"><span class="seasonal-badge">${escapeHtml(badge)}</span><h3>${escapeHtml(flag||'🌍')} ${escapeHtml(city)}</h3><div class="seasonal-card-foot">${isAvailable?`<strong>${t.from} ${money(item.country.price_from)}</strong><span>${seasonalText.view} →</span>`:`<strong>${seasonalText.unavailable}</strong>`}</div></div></article>`;}).join('');
  grid.querySelectorAll('.seasonal-card:not(.is-unavailable)').forEach(card=>{const open=()=>openPlans(card.dataset.country);card.addEventListener('click',open);card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});});
}
function setupSeasonalFilters(){document.querySelectorAll('[data-season-filter]').forEach(button=>button.addEventListener('click',()=>{seasonalFilter=button.dataset.seasonFilter;document.querySelectorAll('[data-season-filter]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active));});renderSeasonal();}));}
async function loadCountries(){try{countries=await api('/api/catalog/countries');if(!countries.length)throw new Error(t.catalogueEmpty);}catch(_){countries=fallbackCountries;toast(t.catalogueUnavailable);}const published=countries.filter(country=>Number(country.product_count||0)>0&&country.price_from!=null),popular=POPULAR_DESTINATIONS.map(iso2=>published.find(country=>country.iso2===iso2)).filter(Boolean),fillers=published.filter(country=>!popular.includes(country)),featured=published.length?[...popular,...fillers].slice(0,4):countries.slice(0,4);renderCountries(featured);renderSeasonal();}
async function openPlans(iso2){
  const country=countries.find(item=>item.iso2===iso2)||{iso2,name:displayNames.of(iso2)||iso2};const name=countryName(country),dialog=q('#plans-dialog');
  q('#plans-content').innerHTML=`<div class="dialog-country-cover"><img id="dialog-country-image" src="${destinationImages[country.iso2]||'/assets/hopon-pool.webp'}" alt="${escapeHtml(t.travelLandscape)} - ${escapeHtml(name)}" referrerpolicy="no-referrer"></div><div class="dialog-inner"><p class="eyebrow">${escapeHtml(country.flag_emoji||'')} ${escapeHtml(name)}</p><h2>${t.choosePlanTitle}</h2><p>${t.planIntro}</p><div class="plan-list"><div class="empty">${t.loadingRates}</div></div></div>`;
  dialog.showModal();resolveCountryImage(country).then(source=>{const image=q('#dialog-country-image');if(image&&source)image.src=source;});
  try{renderPlans(country,await api(`/api/catalog/products?country=${encodeURIComponent(iso2)}`));}catch(_){q('#plans-content .plan-list').innerHTML=`<div class="empty">${t.syncUnavailable}</div>`;}
}
function formatData(mb){if(!Number(mb))return t.unlimited;const value=Number(mb),large=value>=1024,amount=large?value/1024:value,unit=LANG==='fr'?(large?'Go':'Mo'):(large?'GB':'MB');return `${amount.toLocaleString(LOCALES[LANG],{maximumFractionDigits:1})} ${unit}`;}
function friendlyPlanName(country,plan){return `eSIM ${countryName(country)} - ${plan.data_amount_mb?formatData(plan.data_amount_mb):t.unlimited}`;}
function friendlyPlanDetails(plan){return `${plan.duration_days||'—'} ${t.days} · ${t.prepaid} · ${t.noRenewal}`;}
function renderPlans(country,plans){
  const list=q('#plans-content .plan-list');if(!plans.length){list.innerHTML=`<div class="empty">${t.noPlan}</div>`;return;}
  list.innerHTML=plans.map(plan=>`<article class="plan"><div><span class="plan-type">${t.prepaidEsim}</span><h3>${escapeHtml(plan.display_name||friendlyPlanName(country,plan))}</h3><p>${escapeHtml(plan.display_details||friendlyPlanDetails(plan))}</p></div><div class="plan-price"><strong>${money(plan.selling_price_ttc)}</strong><small>${t.taxIncluded}</small></div><ul class="plan-benefits"><li>${t.autoActivation}</li><li>${t.noPhysicalSim}</li><li>${t.noRenewal}</li></ul><button class="button" data-plan='${escapeHtml(JSON.stringify({id:plan.id,name:plan.display_name||friendlyPlanName(country,plan),details:plan.display_details||friendlyPlanDetails(plan),country:countryName(country),price:plan.selling_price_ttc}))}'>${t.choosePlan}</button></article>`).join('');
  list.querySelectorAll('[data-plan]').forEach(button=>button.addEventListener('click',()=>openCheckout(JSON.parse(button.dataset.plan))));
}

let rechargeState={email:'',token:'',esims:[],plans:[]};
function openRecharge(){rechargeState={email:'',token:'',esims:[],plans:[]};q('#recharge-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${t.noAccount}</p><h2>${t.rechargeTitle}</h2><div class="recharge-eligibility"><strong>${rechargeText.only}</strong><span>${rechargeText.lead}</span></div><form id="recharge-email-form" class="recharge-form"><label>${rechargeText.email}<input name="email" type="email" autocomplete="email" required><small>${rechargeText.help}</small></label><button class="button" type="submit">${t.receiveCode}</button><p class="form-message" role="status"></p></form><aside class="external-esim"><strong>${rechargeText.externalTitle}</strong><p>${rechargeText.externalCopy}</p><button type="button" id="external-esim-action">${rechargeText.externalAction} →</button></aside></div>`;const dialog=q('#recharge-dialog');if(!dialog.open)dialog.showModal();q('#recharge-email-form').addEventListener('submit',requestRechargeCode);q('#external-esim-action').onclick=()=>{dialog.close();location.hash='top';setTimeout(()=>q('#destination-search')?.focus(),0);};}
async function requestRechargeCode(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),message=form.querySelector('.form-message');rechargeState.email=String(new FormData(form).get('email')||'').trim().toLowerCase();button.disabled=true;message.classList.remove('error');message.textContent=t.sendingCode;try{const result=await api('/api/recharge/request-code',{method:'POST',body:JSON.stringify({email:rechargeState.email,language:LANG})});q('#recharge-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${t.secureVerification}</p><h2>${t.checkEmail}</h2><p>${escapeHtml(result.message)}</p><form id="recharge-code-form" class="recharge-form"><label>${t.sixDigitCode}<input class="recharge-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="button" type="submit">${t.verifyCode}</button><p class="form-message" role="alert"></p><button class="text-button" type="button" id="recharge-back">${t.otherEmail}</button></form></div>`;q('#recharge-code-form').addEventListener('submit',verifyRechargeCode);q('#recharge-back').onclick=openRecharge;}catch(error){message.textContent=error.message;message.classList.add('error');button.disabled=false;}}
async function verifyRechargeCode(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),message=form.querySelector('.form-message');button.disabled=true;message.textContent=t.verifying;message.classList.remove('error');try{const result=await api('/api/recharge/verify-code',{method:'POST',body:JSON.stringify({email:rechargeState.email,code:String(new FormData(form).get('code')||''),language:LANG})});rechargeState.token=result.token;rechargeState.esims=result.esims;renderRechargeChoice();}catch(error){message.textContent=error.message;message.classList.add('error');button.disabled=false;}}
function renderRechargeChoice(){
  const availableCountries=countries.length?countries:fallbackCountries;
  q('#recharge-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${t.esimFound}</p><h2>${t.chooseRecharge}</h2><form id="recharge-choice-form" class="recharge-form"><label>${t.yourEsim}<select name="esim_id" required>${rechargeState.esims.map(esim=>`<option value="${escapeHtml(esim.id)}">${escapeHtml(esim.label)}</option>`).join('')}</select></label><label>${t.destination}<select name="country" required><option value="">${t.chooseDestination}</option>${availableCountries.map(country=>`<option value="${escapeHtml(country.iso2)}">${escapeHtml(country.flag_emoji||'🌍')} ${escapeHtml(countryName(country))}</option>`).join('')}</select></label><label>${t.plan}<select name="product_id" required disabled><option value="">${t.chooseDestinationFirst}</option></select></label><aside id="recharge-contract-summary" class="contract-summary" hidden></aside><label class="check-label"><input name="terms_accepted" type="checkbox" required><span>${legalText(t.termsAccept)}</span></label><label class="check-label"><input name="immediate_delivery_consent" type="checkbox" required><span>${t.rechargeWaiver}</span></label><button class="button" type="submit" disabled>${t.choosePlan}</button><p class="notice">${t.rechargeNotice}</p><p class="form-message" role="alert"></p></form></div>`;
  const form=q('#recharge-choice-form');form.elements.country.addEventListener('change',loadRechargePlans);form.elements.product_id.addEventListener('change',updateRechargeButton);form.addEventListener('submit',startRechargeCheckout);
}
async function loadRechargePlans(event){const form=event.target.form,select=form.elements.product_id,button=form.querySelector('button[type=submit]');select.disabled=true;button.disabled=true;select.innerHTML=`<option>${t.loadingPlans}</option>`;if(!event.target.value){select.innerHTML=`<option value="">${t.chooseDestinationFirst}</option>`;return;}try{rechargeState.plans=await api(`/api/catalog/products?country=${encodeURIComponent(event.target.value)}`);select.innerHTML=`<option value="">${t.choosePlan}</option>`+rechargeState.plans.map(plan=>`<option value="${escapeHtml(plan.id)}">${escapeHtml(plan.display_name)} — ${money(plan.selling_price_ttc)}</option>`).join('');select.disabled=!rechargeState.plans.length;if(!rechargeState.plans.length)select.innerHTML=`<option value="">${t.noPublishedPlan}</option>`;}catch(error){select.innerHTML=`<option value="">${t.plansUnavailable}</option>`;form.querySelector('.form-message').textContent=error.message;}}
function updateRechargeButton(event){const plan=rechargeState.plans.find(item=>item.id===event.target.value),button=event.target.form.querySelector('button[type=submit]'),summary=q('#recharge-contract-summary');button.disabled=!plan;button.textContent=plan?`${t.continuePayment} · ${money(plan.selling_price_ttc)}`:t.choosePlan;if(summary){summary.hidden=!plan;summary.innerHTML=plan?`<strong>${cartText.contractTitle}</strong><span>${escapeHtml(plan.display_name)} · ${escapeHtml(plan.display_details||'')} · ${money(plan.selling_price_ttc)} ${t.taxIncluded}<br>${cartText.contractCopy}</span>`:'';}}
async function startRechargeCheckout(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type=submit]'),message=form.querySelector('.form-message'),values=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent=t.openingPayment;try{const result=await api('/api/recharge/checkout/session',{method:'POST',headers:{Authorization:`Bearer ${rechargeState.token}`},body:JSON.stringify({esim_id:values.esim_id,product_id:values.product_id,terms_accepted:values.terms_accepted==='on',immediate_delivery_consent:values.immediate_delivery_consent==='on',language:LANG})});location.href=result.url;}catch(error){message.textContent=error.message;message.classList.add('error');button.disabled=false;button.textContent=t.retry;}}

const CART_STORAGE_KEY='hopon-esim-cart-v1';
const validCartItem=item=>item&&item.id&&item.name&&Number(item.price)>0&&item.recipient_name&&item.recipient_email;
let cart=(()=>{try{const value=JSON.parse(sessionStorage.getItem(CART_STORAGE_KEY)||'[]');return Array.isArray(value)?value.filter(validCartItem).slice(0,10):[];}catch(_){return[];}})();
function analyticsEvent(name,parameters={}){if(typeof window.hoponAnalyticsEvent==='function')window.hoponAnalyticsEvent(name,parameters);}
function cartAnalyticsItems(){return cart.map((item,index)=>({item_id:item.id,item_name:item.name,index,price:Number(item.price),quantity:1}));}
function saveCart(){try{sessionStorage.setItem(CART_STORAGE_KEY,JSON.stringify(cart));}catch(_){}updateCartButton();}
function updateCartButton(){const button=q('#cart-button');if(button)button.innerHTML=`<span aria-hidden="true">🛒</span><span class="cart-label">${cartText.cart}</span><b>${cart.length}</b>`;}
function setupCart(){const host=q('.header-actions');if(!host||q('#cart-button'))return;const button=document.createElement('button');button.type='button';button.id='cart-button';button.className='cart-button';button.setAttribute('aria-label',cartText.title);button.onclick=openCart;host.prepend(button);updateCartButton();}
function openCheckout(plan){
  q('#plans-dialog').close();const dialog=q('#checkout-dialog');
  q('#checkout-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${cartText.cart}</p><h2>${cartText.recipientTitle}</h2><p>${cartText.recipientLead}</p><div class="checkout-summary"><strong>${escapeHtml(plan.name)}</strong><small>${escapeHtml(plan.details||'')}</small><span>${money(plan.price)} ${t.taxIncluded}</span></div><form id="recipient-form" class="checkout-form"><label>${cartText.recipientName}<input name="recipient_name" autocomplete="name" required minlength="2"></label><label>${cartText.recipientEmail}<input name="recipient_email" type="email" autocomplete="email" required><small>${cartText.recipientHelp}</small></label><p class="notice">${cartText.recipientPrivacy}</p><button class="button" type="submit">${cartText.add}</button><p class="notice">${cartText.limit}</p></form></div>`;
  if(!dialog.open)dialog.showModal();
  q('#recipient-form').addEventListener('submit',event=>{event.preventDefault();if(cart.length>=10){toast(cartText.limit);return;}const values=Object.fromEntries(new FormData(event.currentTarget));cart.push({...plan,recipient_name:String(values.recipient_name||'').trim(),recipient_email:String(values.recipient_email||'').trim().toLowerCase()});saveCart();analyticsEvent('add_to_cart',{currency:'EUR',value:Number(plan.price),items:[{item_id:plan.id,item_name:plan.name,price:Number(plan.price),quantity:1}]});toast(cartText.added);openCart();});
}
function openCart(){
  const dialog=q('#checkout-dialog');analyticsEvent('view_cart',{currency:'EUR',value:cart.reduce((sum,item)=>sum+Number(item.price),0),items:cartAnalyticsItems()});
  if(!cart.length){q('#checkout-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${cartText.cart}</p><h2>${cartText.title}</h2><div class="empty">${cartText.empty}</div><button class="button" type="button" data-add-another>${cartText.addAnother}</button></div>`;}
  else{const total=cart.reduce((sum,item)=>sum+Number(item.price),0),first=cart[0];q('#checkout-content').innerHTML=`<div class="dialog-inner"><p class="eyebrow">${cartText.cart} · ${cart.length}</p><h2>${cartText.title}</h2><div class="cart-list">${cart.map((item,index)=>`<article class="cart-item"><div><strong>${escapeHtml(item.name)}</strong><span>${escapeHtml(item.details||'')}</span><span>${escapeHtml(item.recipient_name)} · ${escapeHtml(item.recipient_email)}</span></div><b>${money(item.price)}</b><button type="button" data-remove-cart="${index}" aria-label="${cartText.remove} ${escapeHtml(item.name)}">×</button></article>`).join('')}</div><div class="cart-total"><strong>Total</strong><b>${money(total)} ${t.taxIncluded}</b></div><p class="notice">${cartText.correctable}</p><button class="text-button cart-add-another" type="button" data-add-another>+ ${cartText.addAnother}</button><form id="cart-checkout-form" class="checkout-form cart-checkout-form"><h3>${cartText.payerTitle}</h3><label>${cartText.payerName}<input name="payer_name" autocomplete="name" value="${escapeHtml(first.recipient_name)}" required minlength="2"></label><label>${cartText.payerEmail}<input name="payer_email" type="email" autocomplete="email" value="${escapeHtml(first.recipient_email)}" required><small>${cartText.payerHelp}</small></label><aside class="contract-summary"><strong>${cartText.contractTitle}</strong><span>${cartText.contractCopy}</span></aside><label class="check-label"><input name="esim_compatible" type="checkbox" required><span>${cartText.compatibility}</span></label><label class="check-label"><input name="terms_accepted" type="checkbox" required><span>${legalText(t.termsAccept)}</span></label><label class="check-label"><input name="immediate_delivery_consent" type="checkbox" required><span>${t.purchaseWaiver}</span></label><button class="button" type="submit">${cartText.pay} · ${money(total)}</button><p class="notice">${t.checkoutNotice}</p></form></div>`;}
  if(!dialog.open)dialog.showModal();q('[data-add-another]').onclick=()=>{dialog.close();location.hash='top';setTimeout(()=>q('#destination-search')?.focus(),0);};
  document.querySelectorAll('[data-remove-cart]').forEach(button=>button.onclick=()=>{cart.splice(Number(button.dataset.removeCart),1);saveCart();openCart();});
  q('#cart-checkout-form')?.addEventListener('submit',startCheckout);
}
async function startCheckout(event){
  event.preventDefault();const button=event.currentTarget.querySelector('button[type=submit]'),values=Object.fromEntries(new FormData(event.currentTarget)),total=cart.reduce((sum,item)=>sum+Number(item.price),0);button.disabled=true;button.textContent=t.openingPayment;
  const payload={payer_name:String(values.payer_name||'').trim(),payer_email:String(values.payer_email||'').trim().toLowerCase(),items:cart.map(item=>({product_id:item.id,recipient_name:item.recipient_name,recipient_email:item.recipient_email})),esim_compatible:values.esim_compatible==='on',terms_accepted:values.terms_accepted==='on',immediate_delivery_consent:values.immediate_delivery_consent==='on',language:LANG,partner_code:PARTNER.code||'',partner_source:PARTNER.source||'link'};
  analyticsEvent('begin_checkout',{currency:'EUR',value:total,items:cartAnalyticsItems()});
  try{const result=await api('/api/checkout/session',{method:'POST',body:JSON.stringify(payload)});location.href=result.url;}catch(error){toast(error.message);button.disabled=false;button.textContent=`${cartText.pay} · ${money(total)}`;}
}
async function showCheckoutSuccess(sessionId){
  const purchasedItems=cartAnalyticsItems();cart=[];saveCart();q('#checkout-content').innerHTML=`<div class="dialog-inner success-state"><div class="success-icon">✓</div><p class="eyebrow">${t.paymentConfirmed}</p><h2 id="success-title">${t.orderPreparing}</h2><p id="success-copy">${t.confirmationEmail}</p><div id="delivery-status" class="delivery-status">${t.preparing}</div><p class="notice">${t.canClose}</p><button class="button button-secondary" data-close-success>${t.continue}</button></div>`;const dialog=q('#checkout-dialog');if(!dialog.open)dialog.showModal();q('[data-close-success]').onclick=()=>{dialog.close();history.replaceState({},'',location.pathname);};
  for(let attempt=0;attempt<20;attempt++){try{const result=await api(`/api/checkout/status?session_id=${encodeURIComponent(sessionId)}`),status=q('#delivery-status'),multiple=result.order_type==='multi_esim'&&Number(result.item_count)>1;if(result.order_type==='recharge'){q('#success-title').textContent=t.rechargePreparing;q('#success-copy').textContent=t.rechargePreparingCopy;}else if(multiple){q('#success-title').textContent=cartText.multiPreparing;q('#success-copy').textContent=cartText.multiPreparingCopy;status.textContent=cartText.deliveryProgress.replace('{delivered}',Number(result.delivered_count||0)).replace('{total}',Number(result.item_count||0));}else if(result.order_type==='new_esim'||result.order_type==='multi_esim'){q('#success-title').textContent=t.esimPreparing;q('#success-copy').textContent=t.esimPreparingCopy;}if(result.status==='delivered'){status.textContent=multiple?cartText.multiDelivered:result.order_type==='recharge'?t.rechargeDelivered:t.esimDelivered;status.classList.add('delivered');const key=`hopon-purchase-${result.analytics_reference||'completed'}`;if(!sessionStorage.getItem(key)){analyticsEvent('purchase',{transaction_id:result.analytics_reference,currency:result.currency||'EUR',value:Number(result.total_ttc||0),item_count:Number(result.item_count||1),items:purchasedItems});sessionStorage.setItem(key,'1');}return;}if(result.status==='support_required'){status.textContent=multiple?cartText.multiSupport:t.supportRequired;return;}}catch(_){}await new Promise(resolve=>setTimeout(resolve,3000));}
}

function setupSearch(){const input=q('#destination-search'),results=q('#search-results'),form=q('#hero-search');if(!input||!results||!form)return;const show=()=>{const term=input.value.trim().toLocaleLowerCase(LOCALES[LANG]),matches=countries.filter(country=>countryName(country).toLocaleLowerCase(LOCALES[LANG]).includes(term)).slice(0,6);results.innerHTML=matches.map(country=>`<button type="button" data-iso="${country.iso2}">${escapeHtml(country.flag_emoji||'🌍')} ${escapeHtml(countryName(country))}</button>`).join('');results.hidden=!term||!matches.length;results.querySelectorAll('button').forEach(button=>button.onclick=()=>{results.hidden=true;openPlans(button.dataset.iso);});};input.addEventListener('input',show);form.addEventListener('submit',event=>{event.preventDefault();const first=results.querySelector('button')||countries.find(country=>countryName(country).toLocaleLowerCase(LOCALES[LANG])===input.value.toLocaleLowerCase(LOCALES[LANG]));if(first)openPlans(first.dataset?.iso||first.iso2);else toast(t.chooseList);});}
function rotateCities(){const word=q('#city-word');if(!word)return;let index=0;setInterval(()=>{index=(index+1)%t.cities.length;word.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:360});word.textContent=t.cities[index];},2300);}

document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();}));
document.querySelectorAll('[data-recharge-trigger]').forEach(button=>button.onclick=()=>{q('#main-nav').classList.remove('open');openRecharge();});
q('.menu-button').onclick=event=>{const nav=q('#main-nav'),open=nav.classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',open);};
q('#show-all').onclick=()=>renderCountries(countries);
setupCart();
const checkoutParams=new URLSearchParams(location.search);
const checkoutSessionId=window.HOPON_CHECKOUT_SESSION_ID||checkoutParams.get('session_id');
if(checkoutParams.get('checkout')==='success'&&checkoutSessionId)showCheckoutSuccess(checkoutSessionId);
if(checkoutParams.get('checkout')==='cancelled')toast(t.cancelled);
setupSeasonalFilters();loadCountries().then(()=>{setupSearch();const requested=String(checkoutParams.get('destination')||'').toUpperCase();if(/^[A-Z]{2}$/.test(requested)&&countries.some(country=>country.iso2===requested))openPlans(requested);});rotateCities();
